import path from 'path';
import fs from 'fs';
import { spawnSync } from 'child_process';
import { log } from './logger.js';
export async function runGradleBuild(config, projectDirectory, mode) {
    const gradle = resolveGradle(projectDirectory);
    const task = mode === 'release' ? 'assembleRelease' : 'assembleDebug';
    const buildType = mode;
    log.step(`Running Gradle: ${task}...`);
    log.dim(`  Gradle: ${gradle}`);
    log.blank();
    const result = spawnSync(gradle, [task, '--stacktrace'], { cwd: projectDirectory, stdio: 'inherit', env: { ...process.env, JAVA_OPTS: '-Xmx4096m' } });
    log.blank();
    if (result.status !== 0) {
        log.error(`Gradle build failed (exit ${result.status})`);
        if (result.error)
            log.dim(result.error.message);
        process.exit(result.status ?? 1);
    }
    const apkDirectory = path.join(projectDirectory, `app/build/outputs/apk/${buildType}`);
    if (!fs.existsSync(apkDirectory)) {
        log.error(`APK output not found: ${apkDirectory}`);
        process.exit(1);
    }
    const apkFiles = fs.readdirSync(apkDirectory).filter(f => f.endsWith('.apk'));
    if (!apkFiles.length) {
        log.error('No APK found in build output.');
        process.exit(1);
    }
    const apkSource = path.join(apkDirectory, apkFiles[0]);
    const apkName = `${config.artifact}-${buildType}.apk`;
    const apkDestination = path.resolve(process.cwd(), apkName);
    fs.copyFileSync(apkSource, apkDestination);
    return apkDestination;
}
function resolveGradle(projectDirectory) {
    const isWindows = process.platform === 'win32';
    const wrapper = path.join(projectDirectory, isWindows ? 'gradlew.bat' : 'gradlew');
    if (fs.existsSync(wrapper)) {
        try {
            fs.chmodSync(wrapper, 0o755);
        }
        catch { }
        return wrapper;
    }
    const gradlePath = spawnSync(isWindows ? 'where' : 'which', ['gradle'], { encoding: 'utf8' });
    if (gradlePath.status === 0 && gradlePath.stdout.trim())
        return gradlePath.stdout.trim().split('\n')[0];
    log.error('Gradle not found. Install Gradle or set ANDROID_HOME.');
    log.dim('https://gradle.org/install/');
    process.exit(1);
}
export function ensureGradleWrapper(projectDirectory) {
    const isWindows = process.platform === 'win32';
    const wrapper = path.join(projectDirectory, isWindows ? 'gradlew.bat' : 'gradlew');
    if (fs.existsSync(wrapper))
        return;
    const gradlePath = spawnSync(isWindows ? 'where' : 'which', ['gradle'], { encoding: 'utf8' });
    if (gradlePath.status === 0 && gradlePath.stdout.trim()) {
        const gradleWrapper = spawnSync(gradlePath.stdout.trim().split('\n')[0], ['wrapper'], { cwd: projectDirectory, stdio: 'inherit' });
        if (gradleWrapper.status === 0) {
            log.dim('  gradlew generated');
            return;
        }
    }
    if (!isWindows) {
        fs.writeFileSync(wrapper, `#!/usr/bin/env sh
APP_HOME="$(cd "$(dirname "$0")" && pwd)"
JAR="$APP_HOME/gradle/wrapper/gradle-wrapper.jar"
if [ -f "$JAR" ]; then exec java -jar "$JAR" "$@"; fi
exec gradle "$@"`, { mode: 0o755 });
    }
    else {
        fs.writeFileSync(wrapper, `@echo off
set JAR=%~dp0gradle\\wrapper\\gradle-wrapper.jar
if exist "%JAR%" ( java -jar "%JAR%" %* ) else ( gradle %* )`);
    }
    log.dim('  gradlew bootstrap script written');
}
